from 写入第二遍 import add
add('17_002',12,'16:9，武士正面头肩与抬手近景；起幅保留头罩顶端与胸前松弯的手指，镜头由抬手缓缓上摇到眼缝及头顶滴落形，停在完整头肩关系。','武士把一只空手抬在胸前，指节先松开再缓慢弯拢，头朝青略低；他在前半句维持狭窄眼缝，肩膀随平稳发声起伏。头罩顶端一小缕浅色黏稠物沿表面向下拖出，停到额顶边缘。他说到后半句，举起的手握拢收向胸口，头重新正对青，围布下胸口的吸气幅度加大。','暗玫瑰灰向浅米粉过渡的图形渐变底场，四周无具象装饰；不把底场当真实粉色烟雾。','人物仍受空地冷白柔光，图形底场不向皮肤和衣装投射额外彩光。','围布内平稳低气息，手指弯拢的布料轻响，句尾吸气加深。',japanese=['だが、何世紀もの間で、人間からこれほどの刺激を受けたのは初めてだ。','お前には、俺の半分の実力を見せる価値がある。'],tone='满足中带评判，后句说得确定而不兴奋乱喊。',phase='state',kind='mixed',node={'武士.阶段':'宣布半数实力并蓄起变身'},pcard={'opening':'武士对刚才交手感到刺激，仍以评判者自居。','beats':['松弯手指，略压头说前句','手握拢收胸，吸气加深'],'coupling':'发声从调侃过渡到准备展示实力。','landing':'注意锁住青，变身准备已积起。'},background_mode='graphic')
add('17_003',10,'16:9，青侧面胸上近景，面朝画面左侧的武士，左半留出对手方向的负空间；机位固定，脸、颈肩和一部分收起的手在画内。','青听完后先把嘴角扬起来，侧脸转向武士，眼睛睁大作出刻意轻松的样子；她开口讥讽时抬了抬下巴，额侧汗珠却继续滑下。后一句她把松垂的手重新收成拳，肩背从疲态中撑起，笑意收窄成挑衅的弯角，脚下站位不再后退。','远处空地薄尘与铅蓝天空虚成上下两层，原作中性的灰底按同场实景补全。','烟囱后侧开阔天空冷白柔光从青侧后照来，脸前由空地敞口给弱中性补光。','青先呼出一口气，再把呼吸压住；衣袖与发梢轻响，远处尘粒落地渐少。',japanese=['ああ、そう？そんなフラグを立てて勝てた人なんて、一人も見たことないけど。','かかってきなさい。'],tone='前句轻讥，后句短促主动，汗与疲态仍在。',phase='state',kind='mixed',node={'青.阶段':'撑起姿态挑衅应战'},pcard={'opening':'青内心已经警惕，外在仍要把对手顶回去。','beats':['刻意带笑、抬下巴说讥讽句','汗仍落，收拳撑肩邀请进攻'],'coupling':'挑衅与身体重新应战一起成立。','landing':'面对武士等待下一招，笑意尚未完全消失。'})
add('18_001',2,'16:9，武士正面中景，头罩留在画面上中部；机位略低，团块自胸前与两侧鼓起时相机缓慢后移，仍让深色块体遮住变化中的完整身体。','武士胸口吸紧后猛然向下压，黑外衣下的体块骤然鼓起，肩侧先扩开、下方团块接着挤进前景；头罩短暂仍在团块上方，随后被顶起的轮廓遮去一部分。衣料尖角被撑向四周，脚下尘粒被震开，完整新形态尚未显出。','深灰鼓胀团块占主要画幅，上方狭窄空隙为淡冷灰天空，外沿有短促放射形。','开阔天空冷白柔光被团块遮出大暗面，边缘一圈亮线随鼓胀扩开。','一声压腹发力、衣料拉紧与团块低闷膨响，脚边砂粒齐抖。',japanese=['ふんっ！'],tone='短促向下发力的喝声。',phase='process',kind='mixed',node={'武士.形态':'鼓胀变身中、全貌被遮','武士.刀':'鞘与背带随破衣挂在身后'},meaning='先保留武士身体被鼓胀团块遮挡的变身阶段，不能在此提前展示最终全貌。')
